<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { api } from '../api';import type { Customer } from '../types';import { ElMessage } from 'element-plus'
const rows=ref<Customer[]>([]),dialog=ref(false),form=reactive<Partial<Customer>>({name:'',level:'normal',status:'active',contactName:'',phone:''})
async function load(){rows.value=(await api.customers()).items} onMounted(load)
function edit(row?:Customer){Object.assign(form,row??{id:undefined,name:'',level:'normal',status:'active',contactName:'',phone:''});dialog.value=true}async function save(){await api.saveCustomer(form);ElMessage.success('已保存');dialog.value=false;load()}
</script>
<template><div class="page"><div class="page-header"><h1 class="page-title">客户管理</h1><el-button type="primary" @click="edit()">新增客户</el-button></div><section class="card"><el-table :data="rows"><el-table-column prop="name" label="客户名称"/><el-table-column prop="level" label="等级"/><el-table-column prop="contactName" label="联系人"/><el-table-column prop="phone" label="电话"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" title="客户"><el-form label-width="80"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="等级"><el-select v-model="form.level"><el-option label="普通" value="normal"/><el-option label="重要" value="important"/><el-option label="重点" value="vip"/></el-select></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactName"/></el-form-item><el-form-item label="电话"><el-input v-model="form.phone"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>

